const names={'logo':'Logo nguồn','icons-static':'Icon SVG · tĩnh và chuyển động','icons-motion':'Vai trò chuyển động','models':'Vật thể3D và ảnh nguồn','ui':'Component giao diện','backgrounds':'Nền thương hiệu','effects':'Animation / Effect','generative-ai':'Hình tạo sinh · hướng dẫn và giới hạn','components':'Component nội dung','reading':'Nhóm nội dung','charts':'Biểu đồ · dữ liệu','maps':'Bản đồ','slides':'Slide16:9','pdf':'Tài liệu đọc','web-app':'Website và App','production':'Design và Edit'};
$('#rules').innerHTML=M.overviewJobs.map(j=>`<section class="rule-section" id="${j.id}" data-overview-id="${j.id}"><h2>${esc(j.title)}</h2><p>${esc(j.purpose)}</p><div class="preview">${j.preview}</div><ul>${j.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p><strong>Nên dùng:</strong> ${esc(j.do)}</p><p><strong>Tránh dùng:</strong> ${esc(j.dont)}</p></section>`).join('');
function sidebar(){let sections=current==='overview'?[['overview','Bắt đầu'],...M.overviewJobs.map(j=>[j.id,j.title])]:[['composition','Quy tắc ghép'],...Object.keys(names).map(f=>['family-'+f,names[f]+' · '+all.filter(x=>x.family===f).length])];$('#contents').innerHTML=sections.map(([id,title])=>`<a href="#${id}">${esc(title)}</a>`).join('');}
function view(v){current=v;$('#overview').hidden=v!=='overview';$('#library').hidden=v!=='library';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===v?'page':'false'));sidebar();if(v==='library')render();}
function fit(){document.querySelectorAll('.asset-preview iframe').forEach(f=>{let b=f.parentElement,r=b.getBoundingClientRect(),record=all.find(x=>x.id===f.closest('[data-library-id]')?.dataset.libraryId),w=record?.previewCanvas?.width||1280,h=record?.previewCanvas?.height||720;try{const native=f.contentDocument?.querySelector('main');if(native){w=native.getBoundingClientRect().width;h=native.getBoundingClientRect().height}}catch{}let s=Math.min(r.width/w,r.height/h);f.style.width=w+'px';f.style.height=h+'px';f.style.transform=`scale(${s})`;f.style.left=(r.width-w*s)/2+'px';f.style.top=(r.height-h*s)/2+'px'});}
