function render(){let q=$('#search').value.toLocaleLowerCase('vi'),rows=all.filter(r=>(active==='all'||r.family===active)&&(r.title+' '+r.id+' '+r.purpose).toLocaleLowerCase('vi').includes(q));$('#library-grid').innerHTML=Object.keys(names).map(f=>{let xs=rows.filter(r=>r.family===f);return xs.length?`<section class="family-section" id="family-${f}"><h2>${esc(names[f])} · ${xs.length}</h2><div class="record-grid">${xs.map(card).join('')}</div></section>`:''}).join('');$('#count').textContent=rows.length+' mẫu khớp / '+all.length+' mẫu đề xuất';$('#empty').hidden=rows.length>0;requestAnimationFrame(fit);}
