function packet(r){return {schemaVersion:'dax-reuse-packet/v1',systemId:M.system.id,version:M.system.version,status:'proposed-not-admitted',record:r,sourceModel:'system.model.json',limits:r.limits||'Retain source/rights and inspect exact source dependencies.'}}
function open(r,reuse=false){let d=$('#detail');$('#detail-content').innerHTML=`<h2>${esc(r.title)}</h2><p>${esc(r.purpose)}</p>${reuse?'<p>Chọn nội dung hiện tại để sao chép; trình duyệt có thể chặn clipboard tự động.</p><label>Gói nguồn hiện tại<textarea readonly rows="12"></textarea></label>':r.format==='html'?`<iframe title="Bản đầy đủ ${esc(r.title)}" src="${r.file}" sandbox="allow-scripts allow-same-origin"></iframe>`:`<img src="${r.file}" alt="${esc(r.title)}" style="width:200px;height:200px;object-fit:contain">`}<dl><dt>Nguồn</dt><dd>${esc(r.source)}</dd><dt>Giới hạn</dt><dd>${esc(r.limits||r.rights)}</dd><dt>Trạng thái</dt><dd>Đề xuất; chưa nhập thư viện chính thức.</dd></dl>`;if(reuse){d.querySelector('textarea').value=JSON.stringify(packet(r),null,2)}if(!d.open)d.showModal();if(reuse){d.querySelector('textarea').focus();d.querySelector('textarea').select()}}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-detail],[data-reuse],[data-play]');if(!b)return;let r=all.find(r=>r.id===(b.dataset.detail||b.dataset.reuse||b.dataset.play));if(!r)return;if(b.dataset.play){let a=b.closest('article'),on=a.classList.toggle('playing');b.setAttribute('aria-pressed',on);b.textContent=on?'Pause':'Play';return}if(b.dataset.detail){open(r);return}let text=JSON.stringify(packet(r),null,2);try{await navigator.clipboard.writeText(text);$('#status').textContent='Đã sao chép gói nguồn hiện tại.'}catch{open(r,true);$('#status').textContent='Chưa sao chép tự động; gói nguồn được chọn để sao chép thủ công.'}});$('#close').onclick=()=>$('#detail').close();$('#global-pause').onclick=e=>{document.querySelectorAll('.playing').forEach(a=>a.classList.remove('playing'));document.querySelectorAll('[data-play]').forEach(b=>{b.setAttribute('aria-pressed','false');b.textContent='Play'});document.querySelectorAll('iframe').forEach(f=>f.contentWindow?.postMessage({type:'dax-pause'},'*'));$('#status').textContent='Đã dừng chuyển động trong các mẫu hiện có.'};
