document.addEventListener('change',e=>{let sel=e.target.closest('[data-logo-variant]');if(!sel)return;let a=sel.closest('article'),r=all.find(x=>x.id===a.dataset.libraryId),ref=r.variantFiles[sel.value];r.selectedVariant={id:sel.value,...ref};r.file=ref.file;r.sha256=ref.sha256;r.assetDelivery={...r.assetDelivery,file:ref.file,sha256:ref.sha256};a.querySelector('.asset-preview img').src=ref.file;a.querySelector('[data-download-source]').href=ref.file;a.querySelector('a[target=_blank]').href=ref.file});
